[{"order":1,"type":"heading","text":"Spring Data Redis: Caching and Data Storage with Spring Boot"},{"order":2,"type":"paragraph","text":"This tutorial explores how to leverage Spring Data Redis within a Spring Boot application for both caching and persistent data storage. We'll cover setup, configuration, basic operations, and advanced features."},{"order":3,"type":"heading","text":"Prerequisites"},{"order":4,"type":"bullet_point","text":"Java Development Kit (JDK) 8 or higher"},{"order":5,"type":"bullet_point","text":"Maven or Gradle build tool"},{"order":6,"type":"bullet_point","text":"Basic understanding of Spring Boot and Spring Data"},{"order":7,"type":"bullet_point","text":"A running Redis server (local or remote)"},{"order":8,"type":"heading","text":"Project Setup"},{"order":9,"type":"subheading","text":"Creating a Spring Boot Project"},{"order":10,"type":"paragraph","text":"You can create a new Spring Boot project using Spring Initializr (start.spring.io). Add the following dependencies:"},{"order":11,"type":"bullet_point","text":"Spring Web"},{"order":12,"type":"bullet_point","text":"Spring Data Redis (Reactive or Non-Reactive, depending on your needs)"},{"order":13,"type":"bullet_point","text":"Lombok (optional, for reducing boilerplate code)"},{"order":14,"type":"subheading","text":"Adding Dependencies (Maven)"},{"order":15,"type":"code","text":"<dependency>
  <groupId>org.springframework.boot</groupId>
  <artifactId>spring-boot-starter-data-redis</artifactId>
</dependency>
<dependency>
  <groupId>org.springframework.boot</groupId>
  <artifactId>spring-boot-starter-web</artifactId>
</dependency>
<dependency>
  <groupId>org.projectlombok</groupId>
  <artifactId>lombok</artifactId>
  <optional>true</optional>
</dependency>
<dependency>
  <groupId>org.springframework.boot</groupId>
  <artifactId>spring-boot-starter-test</artifactId>
  <scope>test</scope>
</dependency>"},{"order":16,"type":"subheading","text":"Adding Dependencies (Gradle)"},{"order":17,"type":"code","text":"dependencies {
 implementation 'org.springframework.boot:spring-boot-starter-data-redis'
 implementation 'org.springframework.boot:spring-boot-starter-web'
 compileOnly 'org.projectlombok:lombok'
 annotationProcessor 'org.projectlombok:lombok'
 testImplementation 'org.springframework.boot:spring-boot-starter-test'
}"},{"order":18,"type":"heading","text":"Configuration"},{"order":19,"type":"subheading","text":"Redis Connection Configuration"},{"order":20,"type":"paragraph","text":"Configure the connection to your Redis server in `application.properties` or `application.yml`."},{"order":21,"type":"code","text":"# application.properties
spring.redis.host=localhost
spring.redis.port=6379
#spring.redis.password=your_redis_password (optional)"},{"order":22,"type":"subheading","text":"Redis Template Configuration"},{"order":23,"type":"paragraph","text":"The `RedisTemplate` is the central class in Spring Data Redis for performing Redis operations. You can customize it for specific needs, such as serialization."},{"order":24,"type":"code","text":"import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.data.redis.connection.RedisConnectionFactory;
import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.data.redis.serializer.StringRedisSerializer;

@Configuration
public class RedisConfig {

    @Bean
    public RedisTemplate<String, Object> redisTemplate(RedisConnectionFactory redisConnectionFactory) {
        RedisTemplate<String, Object> template = new RedisTemplate<>();
        template.setConnectionFactory(redisConnectionFactory);
        template.setKeySerializer(new StringRedisSerializer());
        template.setValueSerializer(new StringRedisSerializer()); //Or use JdkSerializationRedisSerializer or Jackson2JsonRedisSerializer
        template.setHashKeySerializer(new StringRedisSerializer());
        template.setHashValueSerializer(new StringRedisSerializer()); //Or use JdkSerializationRedisSerializer or Jackson2JsonRedisSerializer
        template.afterPropertiesSet();
        return template;
    }
}"},{"order":25,"type":"paragraph","text":"This configuration creates a `RedisTemplate` that serializes keys and values as Strings.  You can use other serializers like `JdkSerializationRedisSerializer` for Java objects or `Jackson2JsonRedisSerializer` for JSON serialization."},{"order":26,"type":"heading","text":"Using Redis for Data Storage"},{"order":27,"type":"subheading","text":"Creating a Data Model"},{"order":28,"type":"paragraph","text":"Let's create a simple `Product` class."},{"order":29,"type":"code","text":"import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;
import java.io.Serializable;

@Data
@AllArgsConstructor
@NoArgsConstructor
public class Product implements Serializable {

    private String id;
    private String name;
    private double price;
}"},{"order":30,"type":"paragraph","text":"Make sure your class implements `Serializable` if you are using a serializer like `JdkSerializationRedisSerializer`.  If using `Jackson2JsonRedisSerializer`, `Serializable` is not required."},{"order":31,"type":"subheading","text":"Storing and Retrieving Data"},{"order":32,"type":"paragraph","text":"Use the `RedisTemplate` to store and retrieve `Product` objects."},{"order":33,"type":"code","text":"import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.stereotype.Repository;

import java.util.UUID;

@Repository
public class ProductRepository {

    private static final String KEY = "Product";

    @Autowired
    private RedisTemplate<String, Object> redisTemplate;

    public Product save(Product product) {
        product.setId(UUID.randomUUID().toString());
        redisTemplate.opsForHash().put(KEY, product.getId(), product);
        return product;
    }

    public Product findById(String id) {
        return (Product) redisTemplate.opsForHash().get(KEY, id);
    }

    public void delete(String id) {
        redisTemplate.opsForHash().delete(KEY, id);
    }
}"},{"order":34,"type":"paragraph","text":"Here, we're using `opsForHash()` to store products in a Redis hash.  The `KEY` constant represents the hash name. You can also use `opsForValue()` for simple key-value storage."},{"order":35,"type":"subheading","text":"Creating a REST Controller"},{"order":36,"type":"paragraph","text":"Create a simple REST controller to expose the product repository."},{"order":37,"type":"code","text":"import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/products")
public class ProductController {

    @Autowired
    private ProductRepository productRepository;

    @PostMapping
    public Product save(@RequestBody Product product) {
        return productRepository.save(product);
    }

    @GetMapping("/{id}")
    public Product findById(@PathVariable String id) {
        return productRepository.findById(id);
    }

    @DeleteMapping("/{id}")
    public String delete(@PathVariable String id) {
        productRepository.delete(id);
        return "Product deleted";
    }
}"},{"order":38,"type":"heading","text":"Using Redis for Caching"},{"order":39,"type":"subheading","text":"Enabling Caching"},{"order":40,"type":"paragraph","text":"Enable caching in your Spring Boot application by adding the `@EnableCaching` annotation to your main application class or a configuration class."},{"order":41,"type":"code","text":"import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.cache.annotation.EnableCaching;

@SpringBootApplication
@EnableCaching
public class SpringDataRedisApplication {

    public static void main(String[] args) {
        SpringApplication.run(SpringDataRedisApplication.class, args);
    }
}"},{"order":42,"type":"subheading","text":"Caching Methods"},{"order":43,"type":"paragraph","text":"Use the `@Cacheable`, `@CachePut`, and `@CacheEvict` annotations to cache method results."},{"order":44,"type":"code","text":"import org.springframework.cache.annotation.CacheEvict;
import org.springframework.cache.annotation.Cacheable;
import org.springframework.stereotype.Service;

@Service
public class ProductService {

    @Autowired
    private ProductRepository productRepository;

    @Cacheable(value = "products", key = "#id")
    public Product findProductById(String id) {
        System.out.println("Fetching from database: " + id); // Simulate database call
        return productRepository.findById(id);
    }

    @CacheEvict(value = "products", key = "#id")
    public void deleteProduct(String id) {
        productRepository.delete(id);
    }
}"},{"order":45,"type":"paragraph","text":"In this example, `@Cacheable(value = "products", key = "#id")` caches the result of `findProductById` using the product ID as the key.  The `value` attribute specifies the cache name. `@CacheEvict` removes the entry from the cache when a product is deleted."},{"order":46,"type":"paragraph","text":"Modify the controller to use the service:"},{"order":47,"type":"code","text":"import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/products")
public class ProductController {

    @Autowired
    private ProductService productService;

    @GetMapping("/{id}")
    public Product findById(@PathVariable String id) {
        return productService.findProductById(id);
    }

    @DeleteMapping("/{id}")
    public String delete(@PathVariable String id) {
        productService.deleteProduct(id);
        return "Product deleted";
    }
}"},{"order":48,"type":"subheading","text":"Cache Configuration"},{"order":49,"type":"paragraph","text":"You can configure the cache manager in your Spring Boot application.  By default, Spring Boot will configure a `RedisCacheManager` if Spring Data Redis is on the classpath."},{"order":50,"type":"code","text":"import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.data.redis.cache.RedisCacheConfiguration;
import org.springframework.data.redis.cache.RedisCacheManager;
import org.springframework.data.redis.connection.RedisConnectionFactory;
import org.springframework.data.redis.serializer.GenericJackson2JsonRedisSerializer;
import org.springframework.data.redis.serializer.RedisSerializationContext;

import java.time.Duration;

@Configuration
public class CacheConfig {

    @Bean
    public RedisCacheManager cacheManager(RedisConnectionFactory redisConnectionFactory) {
        RedisCacheConfiguration cacheConfiguration = RedisCacheConfiguration.defaultCacheConfig()
                .entryTtl(Duration.ofMinutes(10))
                .disableCachingNullValues()
                .serializeValuesWith(
                        RedisSerializationContext.SerializationPair.fromSerializer(new GenericJackson2JsonRedisSerializer())
                );

        return RedisCacheManager.builder(redisConnectionFactory)
                .cacheDefaults(cacheConfiguration)
                .build();
    }
}"},{"order":51,"type":"paragraph","text":"This example configures the `RedisCacheManager` with a default expiration time of 10 minutes and disables caching of null values.  It also uses `GenericJackson2JsonRedisSerializer` for serializing cache values to JSON."},{"order":52,"type":"heading","text":"Advanced Features"},{"order":53,"type":"subheading","text":"Redis Pub/Sub"},{"order":54,"type":"paragraph","text":"Spring Data Redis supports Redis's publish/subscribe messaging paradigm.  You can use it to build real-time applications."},{"order":55,"type":"subheading","text":"Redis Transactions"},{"order":56,"type":"paragraph","text":"Spring Data Redis allows you to execute multiple Redis commands within a single transaction."},{"order":57,"type":"subheading","text":"Redis Lua Scripting"},{"order":58,"type":"paragraph","text":"You can execute Lua scripts on the Redis server using Spring Data Redis."},{"order":59,"type":"heading","text":"Conclusion"},{"order":60,"type":"paragraph","text":"This tutorial provided a comprehensive overview of using Spring Data Redis for caching and data storage in Spring Boot applications. You learned how to configure Redis, store and retrieve data, implement caching, and explore advanced features.  Remember to choose the appropriate serialization strategy based on your data types and performance requirements."}]
